        });
        if (terminal.length) {
            return { state: terminal[0].conclusion, at: terminal[0].created_at,
                     url: terminal[0].html_url };
        }
        var active = mine.filter(function (r) {
            return r.status === 'queued' || r.status === 'in_progress' ||
                   r.status === 'waiting' || r.status === 'pending';
        });
        if (active.length) {
